26	/**
27	 * Simple JavaBean domain object representing an owner.
28	 *
29	 * @author Ken Krebs
30	 * @author Juergen Hoeller
31	 * @author Sam Brannen
32	 * @author Michael Isvy
33	 */
34	@Entity
35	@Table(name = "owners")
36	public class Owner extends Person {
37	    @Column(name = "address")
38	    @NotEmpty
39	    private String address;
40	
41	    @Column(name = "city")
42	    @NotEmpty
43	    private String city;
44	
45	    @Column(name = "telephone")
46	    @NotEmpty
47	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be a valid E.164 number")
48	    private String telephone;
49	
50	    @Column(name = "email")
51	    private String email;
52	
53	    @Column(name = "customer_code")
54	    private String customerCode;
55	
56	    @Column(name = "registration_date")
57	    private java.time.LocalDate registrationDate;
58	
59	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
60	    private Set<Pet> pets;
61	
62	    @PrePersist
63	    private void defaultRegistrationDate() {
64	        if (this.registrationDate == null) {
65	            this.registrationDate = java.time.LocalDate.now();
66	        }
67	    }
68	
69	    public java.time.LocalDate getRegistrationDate() {
70	        return this.registrationDate;
71	    }
72	
73	    public void setRegistrationDate(java.time.LocalDate registrationDate) {
74	        this.registrationDate = registrationDate;
75	    }
76	
77	    public String getCustomerCode() {
78	        return this.customerCode;
79	    }
80	
81	    /**
82	     * Assign this owner's customerCode as '<LAST3>-<NNNN>', where LAST3 is the
83	     * upper-cased first three letters of the last name and NNNN is a 4-digit,
84	     * zero-padded sequence one greater than the current number of owners.
85	     */
86	    public void assignCustomerCode(int existingOwnerCount) {
87	        String prefix = this.lastName.substring(0, Math.min(3, this.lastName.length())).toUpperCase(Locale.ROOT);
88	        this.customerCode = String.format("%s-%04d", prefix, existingOwnerCount + 1);
89	    }
90	
91	    public String getEmail() {
92	        return this.email;
93	    }
94	
95	    public void setEmail(String email) {
96	        this.email = (email == null) ? null : email.toLowerCase(Locale.ROOT);
97	    }
98	
99	    public String getAddress() {
100	        return this.address;
101	    }
102	
103	    public void setAddress(String address) {
104	        this.address = address;
105	    }
106	
107	    public String getCity() {
108	        return this.city;
109	    }
110	
111	    public void setCity(String city) {
112	        this.city = city;
113	    }
114	
115	    public String getTelephone() {
116	        return this.telephone;
117	    }
118	
119	    public void setTelephone(String telephone) {
120	        this.telephone = TelephoneNumber.toE164(telephone);
121	    }
122	
123	    protected Set<Pet> getPetsInternal() {
124	        if (this.pets == null) {
125	            this.pets = new HashSet<>();
126	        }
127	        return this.pets;
128	    }
129	
130	    protected void setPetsInternal(Set<Pet> pets) {
131	        this.pets = pets;
132	    }
133	
134	    public List<Pet> getPets() {
135	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
136	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
137	        return Collections.unmodifiableList(sortedPets);
138	    }
139	
140	    public void setPets(List<Pet> pets) {
141	        this.pets = new HashSet<>(pets);
142	    }
143	
144	    public void addPet(Pet pet) {
145	        getPetsInternal().add(pet);
146	        pet.setOwner(this);
147	    }
148	
149	    /**
150	     * Return the Pet with the given name, or null if none found for this Owner.
151	     *
152	     * @param name to test
153	     * @return true if pet name is already in use
154	     */
155	    public Pet getPet(String name) {
156	        return getPet(name, false);
157	    }
158	
159	    /**
160	     * Return the Pet with the given name, or null if none found for this Owner.
161	     *
162	     * @param name to test
163	     * @return true if pet name is already in use
164	     */
165	    public Pet getPet(String name, boolean ignoreNew) {
166	        name = name.toLowerCase();
167	        for (Pet pet : getPetsInternal()) {
168	            if (!ignoreNew || !pet.isNew()) {
169	                String compName = pet.getName();
170	                compName = compName.toLowerCase();
171	                if (compName.equals(name)) {
172	                    return pet;
173	                }
174	            }
175	        }
176	        return null;
177	    }
178	
179	    public Pet getPet(Integer petId) {
180	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
181	    }
182	
183	    @Override
184	    public String toString() {
185	        return new ToStringCreator(this)
186	
187	            .append("id", this.getId())
188	            .append("new", this.isNew())
189	            .append("lastName", this.getLastName())
190	            .append("firstName", this.getFirstName())
191	            .append("address", this.address)
192	            .append("city", this.city)
193	            .append("telephone", this.telephone)
194	            .toString();
195	    }
196	}
